function baseline(data,region,year,month){let a=data.filter(d=>d.region===region&&+d.date.slice(0,4)<year&&+d.date.slice(5)===month+1&&d.complete&&d.cases!=null).map(d=>d.cases);return {n:a.length,mean:a.length?a.reduce((x,y)=>x+y,0)/a.length:null}}
